let seq=0,waiters=new Map(),resolveReady,rejectReady;
const ready=new Promise((r,j)=>{resolveReady=r;rejectReady=j;});ready.catch(()=>{});
let worker=new Worker(new URL('./worker.js',import.meta.url),{type:'module'});
worker.onmessage=({data})=>{if(data.ready){s.ready=true;$('#engineStatus').textContent='● Lokale PDF-Engine bereit';resolveReady();return;}const p=waiters.get(data.id);if(p){waiters.delete(data.id);data.error?p.reject(Error(data.error)):p.resolve(data.result);}};
worker.onerror=()=>{const e=Error('Die PDF-Engine konnte nicht geladen werden. Seite neu laden oder lokale Installation prüfen.');rejectReady(e);for(const p of waiters.values())p.reject(e);waiters.clear();$('#engineStatus').textContent='PDF-Engine nicht verfügbar';toast(e.message,true);};
