async function navigate(page){if(s.busy||!s.open)return;s.page=Math.max(0,Math.min(s.info.count-1,page));await run(async()=>{await renderPage();renderInspector();},'Seite wird angezeigt …');}
function placeHit(rect,klass,fn,label){const b=document.createElement('button');b.type='button';b.className='hit-box '+klass;const bb=s.render.bounds;b.style.left=(rect[0]-bb[0])*s.scale+'px';b.style.top=(rect[1]-bb[1])*s.scale+'px';b.style.width=Math.max(5,(rect[2]-rect[0])*s.scale)+'px';b.style.height=Math.max(5,(rect[3]-rect[1])*s.scale)+'px';b.title=label;b.setAttribute('aria-label',label);if(fn)b.onclick=fn;else b.tabIndex=-1;$('#hitLayer').append(b);}
function renderHits(){
  $('#hitLayer').replaceChildren();if(!s.render)return;
  $('#drawCanvas').style.pointerEvents=['select','replace','paragraph','form'].includes(s.tool)?'none':'auto';
  $('#toolHint').textContent=({select:'Wähle ein Werkzeug. Rückgängig mit Strg+Z.',paragraph:'Klicke auf einen Absatz oder ein Textfeld. Position, Größe und Umbruch sind bearbeitbar.', 'paragraph-new':'Ziehe einen Rahmen für einen neuen Absatz.',table:'Ziehe einen Tabellenbereich für den Excel-Export.',replace:'Klicke auf eine Textzeile. Der Ersatz wird in den gewählten Bereich eingepasst.',text:'Ziehe einen Rahmen für deinen Text.',highlight:'Ziehe einen Rahmen über den gewünschten Bereich.',underline:'Ziehe einen Rahmen über die Textzeile.',strike:'Ziehe einen Rahmen über die Textzeile.',redact:'Ziehe einen Bereich zum dauerhaften Entfernen. Exportiere danach eine neue Datei.',draw:'Zeichne direkt auf der Seite.',note:'Klicke auf die Seite, um eine Notiz zu setzen.',rect:'Ziehe ein Rechteck.',ellipse:'Ziehe eine Ellipse.',arrow:'Ziehe vom Pfeilanfang zur Pfeilspitze.',crop:'Ziehe den neuen sichtbaren Seitenausschnitt. Verborgene Inhalte bleiben erhalten.',image:'Ziehe einen Rahmen für dein Bild oder deine Unterschrift.',form:'Klicke auf ein markiertes Formularfeld.'})[s.tool];
  if(s.tool==='replace')for(const line of s.render.lines.filter(x=>x.horizontal))placeHit(line.rect,'',()=>replaceLine(line),'Text korrigieren: '+line.text);
  if(s.tool==='paragraph'){for(const b of (s.render.blocks||[]).filter(b=>b.horizontal))placeHit(b.rect,'',()=>editParagraph(b),'Absatz bearbeiten: '+b.text);for(const a of s.render.annotations.filter(a=>a.type==='FreeText'))placeHit(a.rect,'field',()=>editParagraph({...a,annotation:a.index}),'Textfeld bearbeiten: '+a.text);}
  if(s.tool==='form')for(const field of s.render.fields)placeHit(field.rect,'field',()=>editField(field),field.label);
  for(const hit of s.searchHits.filter(x=>x.page===s.page))for(const q of hit.quads){const xs=[q[0],q[2],q[4],q[6]],ys=[q[1],q[3],q[5],q[7]];placeHit([Math.min(...xs),Math.min(...ys),Math.max(...xs),Math.max(...ys)],'search-hit',null,'Suchtreffer');}
}
function setTool(tool){s.tool=tool;$$('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===tool));if(tool==='highlight'){s.color='#efc944';$('#color')&&($('#color').value=s.color);}renderHits();if(tool==='form'&&!s.render.fields.length)toast('Auf dieser Seite sind keine unterstützten Formularfelder vorhanden.');if(tool==='replace'&&!s.render.lines.length)toast('Kein bearbeitbarer Seitentext gefunden. Für Scans steht die OCR-Texterkennung zur Verfügung.');}
