const fullBtn=(id,label,i='file',primary=false)=>`<button id="${id}" class="${primary?'primary':'secondary'} full-button">${icon(i)}${label}</button>`;
function bind(id,fn){const el=$('#'+id);if(el)el.onclick=fn;}
