    $('#fontFamily').value=s.family;$('#fontFamily').onchange=e=>s.family=e.target.value;$('#color').oninput=e=>s.color=e.target.value;$('#fontSize').onchange=e=>s.size=Math.max(6,Math.min(96,+e.target.value||14));$('#lineWidth').oninput=e=>s.width=+e.target.value;
    $$('[data-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));bind('insertImage',()=>$('#imageInput').click());bind('signature',signature);bind('newParagraph',()=>setTool('paragraph-new'));
    const area=$('#annotations');if(!s.render?.annotations.length)area.innerHTML='<p class="small-note">Noch keine Anmerkungen auf dieser Seite.</p>';else for(const a of s.render.annotations){const row=document.createElement('div');row.className='annotation-row';const text=document.createElement('span');text.textContent=`${a.type}: ${a.text||'Grafik'}`;const b=document.createElement('button');b.textContent='×';b.title='Anmerkung entfernen';b.onclick=()=>mutate('deleteAnnotation',{index:s.page,annotation:a.index},'Anmerkung wird entfernt …');row.append(text,b);area.append(row);}
