    bind('rotate',()=>mutate('pages',{action:'rotate',index:s.page}));bind('duplicate',()=>mutate('pages',{action:'duplicate',index:s.page}));bind('blankPage',()=>mutate('pages',{action:'blank',index:s.page}));
    $('#moveBefore').disabled=s.page===0;$('#moveAfter').disabled=s.page===s.info.count-1;
