    bind('deletePage',async()=>{if(s.info.count<2)return toast('Mindestens eine Seite muss bleiben.');if(await dialog('Seite entfernen',`<p>Seite ${s.page+1} aus dieser Arbeitskopie entfernen?</p>`,{confirm:'Seite entfernen'}))await mutate('pages',{action:'delete',index:s.page});});
    bind('mergeBtn',()=>$('#mergeInput').click());bind('imagePages',()=>$('#imagesInput').click());bind('extract',exportDialog);bind('split',splitPages);
