function coordinates(e){const r=$('#drawCanvas').getBoundingClientRect(),b=s.render.bounds;return [Math.max(b[0],Math.min(b[2],(e.clientX-r.left)/s.scale+b[0])),Math.max(b[1],Math.min(b[3],(e.clientY-r.top)/s.scale+b[1]))];}
let gesture=null;
$('#drawCanvas').onpointerdown=e=>{if(s.busy||!s.open)return;e.preventDefault();const p=coordinates(e);gesture={start:p,last:p,points:[p],tool:s.tool};e.currentTarget.setPointerCapture(e.pointerId);};
$('#drawCanvas').onpointermove=e=>{if(!gesture)return;gesture.last=coordinates(e);gesture.points.push(gesture.last);paintGesture();};
function paintGesture(){const c=$('#drawCanvas'),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);if(!gesture)return;ctx.save();ctx.scale(2*s.scale,2*s.scale);ctx.translate(-s.render.bounds[0],-s.render.bounds[1]);ctx.strokeStyle=s.tool==='redact'?'#18161f':s.color;ctx.lineWidth=s.width;ctx.setLineDash(s.tool==='draw'?[]:[4,3]);const [x,y]=gesture.start,[ex,ey]=gesture.last;if(s.tool==='draw'){ctx.beginPath();gesture.points.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.stroke();}else if(s.tool==='arrow'){ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(ex,ey);ctx.stroke();}else{ctx.fillStyle=s.tool==='redact'?'#16141dcc':'#6251bc20';ctx.fillRect(x,y,ex-x,ey-y);ctx.strokeRect(x,y,ex-x,ey-y);}ctx.restore();}
$('#drawCanvas').onpointercancel=()=>{gesture=null;paintGesture();};
$('#drawCanvas').onpointerup=async e=>{
  if(!gesture)return;const g=gesture;gesture=null;paintGesture();let r=[Math.min(g.start[0],g.last[0]),Math.min(g.start[1],g.last[1]),Math.max(g.start[0],g.last[0]),Math.max(g.start[1],g.last[1])];const kind=g.tool;
  if(kind==='note')r=[g.start[0],g.start[1],g.start[0]+24,g.start[1]+24];
  if(kind!=='draw'&&kind!=='note'&&(r[2]-r[0]<5||r[3]-r[1]<3))return toast('Bitte einen größeren Bereich aufziehen.');
  if(kind==='paragraph-new')return editParagraph({rect:r,text:'',size:s.size,isNew:true});
  if(kind==='table')return officeDialog('xlsx',r);
  const args={index:s.page,kind,rect:r,color:s.color,size:s.size,width:s.width,family:s.family,points:kind==='arrow'?[g.start,g.last]:g.points};
  if(kind==='text'||kind==='note'){const a=await dialog(kind==='text'?'Text ergänzen':'Notiz hinzufügen',`<textarea name="text" rows="5" placeholder="Dein Text …" required></textarea>${kind==='text'?'<p>Die Größe des gewählten Rahmens bestimmt den verfügbaren Platz.</p>':''}`);if(!a)return;args.text=a.text;}
  if(kind==='redact'){const a=await dialog('Bereich schwärzen',`<p>Text, Bilder und Grafiken in diesem Bereich werden in deiner Arbeitskopie entfernt. Prüfe die Auswahl sorgfältig.</p><p>Du kannst den Schritt in dieser Sitzung rückgängig machen. Das Original bleibt unverändert.</p>`,{confirm:'Bereich schwärzen'});if(!a)return;}
  if(kind==='crop'){const a=await dialog('Seite zuschneiden',`<p>Nur der sichtbare Ausschnitt wird geändert. Inhalte außerhalb des Ausschnitts bleiben in der PDF enthalten.</p>`,{confirm:'Ausschnitt übernehmen'});if(!a)return;}
  if(kind==='image'){if(!s.image)return toast('Bitte zuerst ein Bild auswählen.');const ratio=s.image.ratio;const rw=r[2]-r[0],rh=r[3]-r[1];if(rw/rh>ratio)r[2]=r[0]+rh*ratio;else r[3]=r[1]+rw/ratio;args.bytes=s.image.bytes;}
  await mutate('annotate',args,'Änderung wird angewendet …');
};
async function signature(){
  let strokes=[],line=null,canvas;
  const a=await dialog('Deine Unterschrift',`<p>Zeichne mit Maus, Stift oder Finger. Sie wird als Bild eingefügt, ohne Zertifikatssignatur.</p><canvas id="signatureCanvas" class="signature-pad" width="960" height="360"></canvas><button type="button" class="text-button" id="clearSignature">Neu zeichnen</button>`,{confirm:'Auf Seite platzieren',setup(){canvas=$('#signatureCanvas');const ctx=canvas.getContext('2d');ctx.strokeStyle='#252435';ctx.lineWidth=3;ctx.lineCap='round';const pos=e=>{const r=canvas.getBoundingClientRect();return[(e.clientX-r.left)*canvas.width/r.width,(e.clientY-r.top)*canvas.height/r.height];};canvas.onpointerdown=e=>{e.preventDefault();line=[pos(e)];strokes.push(line);canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(!line)return;const p=pos(e);ctx.beginPath();ctx.moveTo(...line.at(-1));ctx.lineTo(...p);ctx.stroke();line.push(p);};canvas.onpointerup=canvas.onpointercancel=()=>line=null;$('#clearSignature').onclick=()=>{strokes=[];ctx.clearRect(0,0,960,360);};}});
  if(a&&strokes.some(x=>x.length>1)){const blob=await new Promise(r=>canvas.toBlob(r));s.image={bytes:new Uint8Array(await blob.arrayBuffer()),ratio:960/360};setTool('image');toast('Ziehe auf der PDF einen Rahmen für deine Unterschrift.');}
}
async function exportDialog(){
  if(!s.open)return;const a=await dialog('Deine PDF exportieren',`<label class="field-label">Dateiname</label><input name="filename" value="${esc(basename())}-bearbeitet.pdf" required><label class="field-label">Seitenbereich (leer = alle)</label><input name="range" placeholder="z. B. 1, 3-5"><label class="field-label">Öffnungspasswort (optional · AES-256)</label><input name="password" type="password" autocomplete="new-password" placeholder="Leer = ohne Passwort"><p class="small-note">Auch bei einem geschützten Original: Ohne neues Passwort wird die exportierte Kopie unverschlüsselt gespeichert.</p><label class="check"><input name="clearMetadata" type="checkbox" checked> Titel, Autor und XMP-Metadaten entfernen</label><label class="check"><input name="flatten" type="checkbox"> Formulare und Anmerkungen fest einbetten</label><label class="check"><input id="rasterOption" name="raster" type="checkbox" ${s.info.redacted?'checked':''}> Bereinigte Bild-PDF erzeugen / Bildkomprimierung</label><div class="info-box ${s.info.redacted?'warning':''}">Bild-PDF: Nur die sichtbaren Seiten werden in eine neue Datei übernommen. Suchbarer Text, Links, Formulare, Anhänge und Signaturen entfallen. ${s.info.redacted?'Nach Schwärzungen empfohlen.':''}</div><div class="form-row"><label><span class="field-label">Bildauflösung</span><select name="dpi"><option value="96">96 dpi · klein</option><option value="144" selected>144 dpi · ausgewogen</option><option value="216">216 dpi · fein</option></select></label><label><span class="field-label">JPEG-Qualität</span><select name="quality"><option value="65">65 %</option><option value="85" selected>85 %</option><option value="95">95 %</option></select></label></div><p class="small-note">Die Dateigröße kann steigen. Vorhandene digitale Signaturen werden durch Änderungen nicht erhalten.</p>`,{confirm:'PDF herunterladen'});
  if(!a)return;await run(async()=>{const bytes=await rpc('export',{...a,flatten:!!a.flatten,raster:!!a.raster,clearMetadata:!!a.clearMetadata,dpi:+a.dpi,quality:+a.quality});download(bytes,a.filename.toLowerCase().endsWith('.pdf')?a.filename:a.filename+'.pdf');toast(`Export erstellt · ${(bytes.length/1024/1024).toFixed(2)} MB. Bitte die gespeicherte Datei prüfen.`);},'PDF wird lokal exportiert …');
}
async function splitPages(images=false){await run(async()=>{const files={};for(let i=0;i<s.info.count;i++){progress(`Seite ${i+1} von ${s.info.count} wird exportiert …`);const key=`Seite-${String(i+1).padStart(3,'0')}`;if(images){const r=await rpc('render',{index:i,scale:1.5,details:false});files[key+'.png']=r.bytes;}else files[key+'.pdf']=await rpc('export',{range:String(i+1),raster:s.info.redacted,clearMetadata:true});}download(zipSync(files,{level:0}),basename()+(images?'-bilder.zip':'-seiten.zip'),'application/zip');},'Seiten werden exportiert …');}
async function stampDialog(kind){const a=await dialog(kind==='numbers'?'Seitennummern einfügen':'Wasserzeichen einfügen',`<label class="field-label">${kind==='numbers'?'Präfix (optional)':'Text'}</label><input name="text" value="${kind==='numbers'?'Seite ':'ENTWURF'}" ${kind==='numbers'?'':'required'}><label class="field-label">Seitenbereich (leer = alle)</label><input name="range" placeholder="z. B. 1-5">`);if(a)await mutate('stamp',{...a,kind});}
async function metadataDialog(){const a=await dialog('Dokumentinformationen',`<label class="field-label">Titel</label><input name="title" value="${esc(s.info.title)}"><label class="field-label">Autor</label><input name="author" value="${esc(s.info.author)}"><label class="field-label">Betreff</label><input name="subject" value="${esc(s.info.subject)}"><label class="check"><input type="checkbox" name="clear"> Stattdessen alle Standard- und XMP-Metadaten entfernen</label>`);if(a)await mutate('metadata',{...a,clear:!!a.clear});}
function rangePages(override){const value=override===undefined?$('#textRange')?.value.trim():override.trim();if(!value)return Array.from({length:s.info.count},(_,i)=>i);const out=[];for(const p of value.split(',')){const m=p.trim().match(/^(\d+)(?:\s*-\s*(\d+))?$/);if(!m)throw Error('Seitenbereich als 1, 3-5 eingeben.');const a=+m[1],b=+(m[2]||m[1]);if(a<1||b<a||b>s.info.count)throw Error('Seitenbereich liegt außerhalb des Dokuments.');for(let i=a;i<=b;i++)if(!out.includes(i-1))out.push(i-1);}return out;}
async function extractText(inside=false){const fn=async()=>{const pages=rangePages();const result=await rpc('text',{pages});s.source=result.map(r=>r.text.trim()).filter(Boolean).join('\n\n');s.translated='';s.translationIncomplete=false;$('#textOutput').value=s.source;if(!s.source)throw Error('Kein Text gefunden. Bei Scans bitte die OCR-Texterkennung verwenden.');toast(`Text aus ${pages.length} Seite(n) ausgelesen.`);};if(inside)return fn();return run(fn,'Text wird ausgelesen …');}
async function ocr(){
  await run(async()=>{const pages=rangePages();progress('Lokale OCR wird geladen …');const {default:Tesseract}=await import('./vendor/ocr/tesseract.esm.min.js');
    const base=new URL('./vendor/',location.href);
    let workerOCR;try{
      workerOCR=await Tesseract.createWorker(s.ocrLang,1,{workerPath:new URL('./ocr-worker.js',location.href).href,corePath:new URL('ocr/tesseract-core-lstm.wasm.js',base).href,langPath:new URL('lang/',base).href,workerBlobURL:false,cacheMethod:'none',logger:m=>{if(m.status==='recognizing text')progress(`OCR: ${Math.round(m.progress*100)} % der aktuellen Seite …`);},errorHandler:()=>{}},{load_system_dawg:'0',load_freq_dawg:'0'});
      const texts=[];for(const i of pages){progress(`OCR · Seite ${i+1} von ${s.info.count} …`);const r=await rpc('render',{index:i,scale:2.5,details:false});const result=await workerOCR.recognize(new Blob([r.bytes],{type:'image/png'}));texts.push(result.data.text.trim());}
      s.source=texts.join('\n\n');s.translated='';s.translationIncomplete=false;$('#textOutput').value=s.source;toast('OCR abgeschlossen. Bitte den erkannten Text kontrollieren.');
    }finally{await workerOCR?.terminate();}
  },'OCR wird gestartet …');
}
function chunks(text,max=1800){const out=[];let part='';for(const line of text.split('\n')){if(part.length+line.length+1>max&&part){out.push(part);part='';}if(line.length>max){for(let i=0;i<line.length;i+=max)out.push(line.slice(i,i+max));}else part+=(part?'\n':'')+line;}if(part)out.push(part);return out;}
async function translate(){
  if(s.provider==='openrouter')return cloudTranslate();
  s.translationIncomplete=false;
  if(!('Translator' in self))return toast('Lokale Übersetzung ist in diesem Browser nicht verfügbar.',true);
  if(s.sourceLang===s.targetLang)return toast('Bitte zwei unterschiedliche Sprachen wählen.');
  if(!s.source.trim())return toast('Bitte zuerst Text auslesen, OCR starten oder Text eingeben.');
  // create() is called directly under user activation. It never has a remote fallback.
  let translatorPromise;
  try{translatorPromise=self.Translator.create({sourceLanguage:s.sourceLang,targetLanguage:s.targetLang,monitor(m){m.addEventListener('downloadprogress',e=>progress(`Sprachmodell wird geladen · ${Math.round(e.loaded*100)} %`));}});}catch(e){return toast(e.message,true);}
  await run(async()=>{let translator;try{translator=await translatorPromise;const parts=chunks(s.source),out=[];for(let i=0;i<parts.length;i++){progress(`Lokal übersetzen · Abschnitt ${i+1} von ${parts.length} …`);out.push(await translator.translate(parts[i]));}s.translated=out.join('\n\n');toast('Übersetzung fertig. Unter „Text & Übersetzung prüfen“ vergleichen.');}finally{translator?.destroy();}},'Lokales Sprachmodell wird vorbereitet …');
  if(s.translated)await reviewText();
}
async function reviewText(){const a=await dialog('Text prüfen',`${s.translationIncomplete?'<div class="info-box warning">Unvollständige Übersetzung: Der Vorgang wurde abgebrochen oder ist fehlgeschlagen. Es sind nur bereits abgeschlossene Abschnitte enthalten.</div>':''}<p>Du kannst beide Fassungen korrigieren. PDFs werden als neu gesetzte Textausgabe gespeichert.</p><div class="two-columns"><label><span class="field-label">Ausgangstext</span><textarea name="source">${esc(s.source)}</textarea></label><label><span class="field-label">Übersetzung</span><textarea name="translated" placeholder="Noch keine Übersetzung vorhanden.">${esc(s.translated)}</textarea></label></div><label class="check"><input type="checkbox" name="bilingual"> Beim nächsten Export zweisprachig: Ausgangstext, danach Übersetzung</label>`,{wide:true,confirm:'Text übernehmen'});if(a){s.source=a.source;s.translated=a.bilingual?`AUSGANGSTEXT\n\n${a.source}\n\nÜBERSETZUNG\n\n${a.translated}`:a.translated;$('#textOutput')&&($('#textOutput').value=s.source);}}
async function privacy(){await dialog('Privatsphäre, konkret',`<h3>Was auf deinem Gerät bleibt</h3><p>PDF-Bearbeitung, OCR, Word-/Excel-Export und Zertifikatssignaturen laufen im Browser. Zertifikatsdateien zum Signieren und deren Passwörter werden dabei nicht hochgeladen. PDF-Dateien bleiben bei lokalen Werkzeugen auf deinem Gerät. Es gibt keine Analyse-Tracker.</p><h3>Optionale Cloud-KI</h3><p>Nur wenn du OpenRouter auswählst und die Übersetzung startest, sendet Folio den im Dialog angezeigten Text an OpenRouter und den gewählten Modellanbieter. Dein API-Key geht ausschließlich an OpenRouter. Bei der reinen Textübersetzung wird keine PDF übertragen. Im Modus „PDF mit Layout übersetzen“ werden die ausgewählten sichtbaren PDF-Seiten einschließlich Bildern, Stempeln und Unterschriften als neu erstellte PDF übertragen. Versteckte Inhalte, Anhänge und Metadaten werden dabei nicht mitgesendet. Du kannst stattdessen lokal übersetzen. OpenRouter-Nutzung kann kostenpflichtig sein. Folio fordert Anbieter ohne Datensammlung an; optional sind ausschließlich ZDR-Endpunkte zugelassen. Prüfe zusätzlich deine OpenRouter-Kontoeinstellungen.</p><h3>Was eine Verbindung benötigt</h3><p>Beim Öffnen werden App-Dateien und gegebenenfalls OCR-Dateien vom Hosting-Anbieter geladen. Dabei fallen normale Verbindungsdaten wie IP-Adresse und Zeitpunkt an. Die lokale Browser-Übersetzung kann Sprachmodelle über den Browser-Anbieter herunterladen. Der Dokumenttext wird mit diesen Modellen auf dem Gerät verarbeitet.</p><h3>Speicherung</h3><p>PDFs und Bearbeitungsschritte bleiben im Arbeitsspeicher dieses Tabs. Es gibt keine automatische Dokumentablage. „Offline vorbereiten“ speichert ausschließlich App-Dateien im Browsercache. API-Key und Zertifikatspasswort werden nicht dauerhaft gespeichert. Der API-Key kann in den OpenRouter-Einstellungen gelöscht werden. Nur die gewählte Hell-/Dunkel-Darstellung wird als Einstellung gespeichert.</p><h3>Maximale Kontrolle</h3><p>Für vertrauliche Arbeit: App und Sprachmodelle vorbereiten, anschließend offline arbeiten. Das mitgelieferte lokale Startskript liefert ausschließlich die App über 127.0.0.1 aus und akzeptiert keine Datei-Uploads. Browser-Erweiterungen und die Sicherheit deines Geräts liegen außerhalb dieser App.</p><p><a href="./source.zip" download>Quellcode herunterladen</a> · <a href="./THIRD_PARTY.html">Open-Source-Lizenzen</a></p>`,{confirm:'Verstanden',cancel:false});}
async function help(){await dialog('Was Folio kann',`<p>Folio ist eine erste lokale PDF-Werkstatt, kein vollständiger Ersatz für jede Funktion einer professionellen PDF-Suite.</p><table><tr><td>Bearbeiten</td><td>Absätze in frei positionierbaren Textfeldern bearbeiten, Text hinzufügen und einzelne Zeilen ersetzen; markieren, zeichnen, Formen, Notizen, Bilder, gezeichnete Unterschriften.</td></tr><tr><td>Seiten</td><td>Drehen, duplizieren, verschieben, löschen, zuschneiden, zusammenfügen, aufteilen und Bildseiten ergänzen.</td></tr><tr><td>Formulare</td><td>Vorhandene Text-, Auswahl-, Checkbox- und Radiobutton-Felder ausfüllen. Keine XFA- oder Formularentwurfsfunktion.</td></tr><tr><td>Text & Sprache</td><td>Textauszug, lokale OCR in DE/EN/ZH, OpenRouter-KI mit eigenem Key oder lokale Übersetzung bei Browser-Unterstützung, TXT- und Text-PDF-Export; PDF-Layout-Übersetzung mit Vorschau und korrigierbaren Textfeldern.</td></tr><tr><td>Export & Schutz</td><td>Word-/Excel-Export (Bildseiten oder bearbeitbare Rekonstruktion), lokale RSA-Zertifikatssignatur (P12/PFX), Bereichsexport, PNG/JPEG, ZIP, AES-256-Passwort, Metadaten, Wasserzeichen, Seitennummern, Bildkomprimierung und Schwärzung.</td></tr></table><h3>Noch nicht enthalten</h3><p>Word/Excel → PDF, garantierte Layouttreue bei bearbeitbarer Office-Ausgabe, automatischer Absatzfluss über Seiten, Bearbeitung bestehender Vektorgrafiken, Signaturprüfung und Mehrfachsignaturen, qualifizierte Signaturen und vertrauenswürdige Zeitstempel, PDF/A-Validierung, barrierefreie PDF/UA-Tags, Stapel-OCR mit durchsuchbarer Originalseite und garantierte pixelgenaue Layout-Übersetzung.</p><h3>Tastenkürzel</h3><p>Strg/Cmd+O: Öffnen · Strg/Cmd+S: Export · Strg/Cmd+Z: Rückgängig · Strg/Cmd+Umschalt+Z: Wiederholen.</p><p>Die App wurde ohne Zugriff auf deine echten Dokumente entwickelt. Bei wichtigen Dateien den Export vor Weitergabe prüfen.</p>`,{confirm:'Los geht’s',cancel:false});}
