$('#offlineBtn').onclick=()=>run(async()=>{if(!('serviceWorker' in navigator))throw Error('Offline-Modus wird hier nicht unterstützt.');const reg=await navigator.serviceWorker.register('./sw.js',{scope:'./'});await navigator.serviceWorker.ready;const sw=reg.active||navigator.serviceWorker.controller;if(!sw)throw Error('Bitte einmal neu laden, dann erneut offline vorbereiten.');await new Promise((resolve,reject)=>{const ch=new MessageChannel();ch.port1.onmessage=e=>{if(e.data.error)reject(Error(e.data.error));else if(e.data.done)resolve();else progress(`App für offline vorbereiten · ${e.data.current}/${e.data.total} Dateien`);};sw.postMessage({type:'CACHE_APP'},[ch.port2]);});toast('App und OCR-Dateien sind offline verfügbar. Lokale Übersetzungsmodelle separat vorbereiten. OpenRouter benötigt Internet.');},'Offline-Dateien werden vorbereitet …');
